import { toggleNotificationPreference } from "./actions";

export default function Home() {
  // This would typically come from your database
  const notificationEnabled = true;

  return (
    <main>
      <h1>Settings</h1>
      <p>Please implement a notification toggle with server-side refresh.</p>

      <form
        action={async () => {
          "use server";
          await toggleNotificationPreference(notificationEnabled);
        }}
      >
        <label>
          <input type="checkbox" defaultChecked={notificationEnabled} readOnly />
          Notifications Enabled
        </label>
        <button type="submit">Toggle Notification Preference</button>
      </form>
    </main>
  );
}

